MAP
    NAME "SS_MAP_DRENAJE_RURAL"
     INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB
    LAYER
        PROJECTION
          'init=epsg:32614'
        END #PROJECION
        NAME "SS_MAP_DRENAJE_FLUJO_RURAL"
        CONNECTIONTYPE POSTGIS
        NAME "Flujo"
        INCLUDE 'includes/conexion.map'
        DATA "geometry from (select ls.gid as gid, ls.diametro as diametro, ls.geometry as geometry from lineassec ls WHERE ls.cl_responsable_mantenimiento=3) as tmp using unique gid using srid=32614"
        PROCESSING "CLOSE_CONNECTION=DEFER"  # Reutiliza conexiones para múltiples consultas
        PROCESSING "POSTGIS_FILTER=YES"      # Filtra geometrías en el lado del servidor
        STATUS DEFAULT
        TYPE line
        MINSCALE 1
        MAXSCALE 15000
        CLASS
            NAME "Flujo"
            STYLE
                COLOR 161 102 50
                GAP -60
                SIZE 15
                SYMBOL "flechas"
            END # STYLE
        END #CLASS
    END #LAYER
    LAYER
         PROJECTION
          'init=epsg:32614'
        END #PROJECION
        NAME "SS_MAP_DRENAJE_UBICACION_RURAL"
        CONNECTIONTYPE POSTGIS
        DATA "geometry from (select ls.gid as gid, ls.diametro as diametro, ls.geometry as geometry from lineassec ls WHERE ls.cl_responsable_mantenimiento=3) as tmp using unique gid using srid=32614"
        PROCESSING "CLOSE_CONNECTION=DEFER"  # Reutiliza conexiones para múltiples consultas
        PROCESSING "POSTGIS_FILTER=YES"      # Filtra geometrías en el lado del servidor
        INCLUDE 'includes/conexion.map'
        STATUS DEFAULT
        TYPE line
        MINSCALE 1
        MAXSCALE 15000
        LABELITEM "diametro"
        CLASS
            NAME "Tuberia con diametro"
            STYLE
                SYMBOL 0
                COLOR 161 102 50
            END #STYLE
            LABEL
                TYPE TRUETYPE
                FONT "arial"
                SIZE 19
                COLOR 0 0 0
                OUTLINECOLOR 254 254 254
            END #LABEL
        END #CLASS
    END #LAYER
END #MAP

